// ---- thin C wrapper to a stable, simple signature ----
extern "C" void baxter_crba(const double q[14], double M_upper[105]) {
  const double* in[1]  = { q };
  double*       out[1] = { M_upper };
  // No atomic functions inside CRBA; zero-init the dispatch table.
  struct LangCAtomicFun atomic_fun = {};
  baxter_crba_forward_zero(in, out, atomic_fun);
}
